import {app,BrowserWindow} from 'electron';import {createServer} from 'node:http';import {mkdtemp,writeFile} from 'node:fs/promises';import {join,resolve} from 'node:path';import assert from 'node:assert/strict';
import {attachPlaywrightView} from '../../packages/browser/src/playwright-view.js';import {inspectResumeInputs,selectResumeFile,resumeFileAccepted} from '../../packages/browser/src/resume-upload.js';import {runUniversalFormAgent} from '../../packages/agent/src/universal-form-agent.js';import {BackgroundModelProvider} from '../../packages/agent/src/background-model-provider.js';import {profile as fixtureProfile} from './moka-form.js';
const directory=await mkdtemp(resolve('.backups/resume-repair-native-'));app.setPath('userData',directory);app.setPath('sessionData',directory);app.setName('OfferFlash Resume Repair Check');await app.whenReady();
let requests=0;const server=createServer(async(request,response)=>{
 if(request.url==='/v1/chat/completions'){
  let body='';for await(const chunk of request)body+=chunk;const payload=JSON.parse(body);requests++;
  let observation='';for(const message of payload.messages??[]){try{const parsed=JSON.parse(typeof message.content==='string'?message.content:'');if(parsed.offerflashInitialObservation)observation=parsed.offerflashInitialObservation.observation;}catch{}}
  if(!observation){response.writeHead(500);response.end('missing fixture observation');return;}
  const common={id:'local-plan',object:'chat.completion.chunk',created:1,model:'fixture-only'};response.writeHead(200,{'content-type':'text/event-stream'});response.write('data: '+JSON.stringify({...common,choices:[{index:0,delta:{role:'assistant',tool_calls:[{index:0,id:'apply-once',type:'function',function:{name:'apply_application_plan',arguments:JSON.stringify({observation,mappings:[],selections:[],drafts:[]})}}]},finish_reason:null}]})+'\n\n');response.write('data: '+JSON.stringify({...common,choices:[{index:0,delta:{},finish_reason:'tool_calls'}],usage:{prompt_tokens:10,completion_tokens:2,total_tokens:12}})+'\n\n');response.end('data: [DONE]\n\n');return;
 }
 response.setHeader('content-type','text/html;charset=utf-8');response.end(`<!doctype html><title>Local upload contract only</title><label>上传简历<input id="resume" type="file" accept=".pdf,.docx" onchange="window.changes=(window.changes||0)+1;document.querySelector('#name').value='wrong parser name';document.querySelector('#phone').value='wrong parser phone'"></label><label>证件照<input id="photo" type="file" accept="image/*"></label><label>姓名<input id="name"></label><label>手机号<input id="phone"></label><label>补充说明<textarea id="extra"></textarea></label><button onclick="window.submissions=(window.submissions||0)+1">提交申请</button>`);
});await new Promise<void>(done=>server.listen(0,'127.0.0.1',done));const address=server.address();assert.ok(address&&typeof address!=='string');const origin=`http://127.0.0.1:${address.port}`;
const window=new BrowserWindow({show:false,webPreferences:{sandbox:true,contextIsolation:true,nodeIntegration:false}});let attachment:Awaited<ReturnType<typeof attachPlaywrightView>>|undefined,provider:BackgroundModelProvider|undefined;const checks:string[]=[];let failed=false;
try{
 await window.loadURL(origin+'/apply');attachment=await attachPlaywrightView(window.webContents);const page=attachment.page;const scan=await inspectResumeInputs(page);assert.equal(scan.targets.filter(target=>target.recommended).length,1);const target=scan.targets.find(target=>target.recommended)!;assert.equal(target.label,'上传简历');checks.push('resume-input-distinguished-from-photo');
 assert.ok(resumeFileAccepted(target.accept,'fictional.pdf'));assert.equal(resumeFileAccepted('image/*','fictional.pdf'),false);
 let guards=0,attempts=0;const inspection={url:page.url(),documentRevision:0,targets:scan.targets};await selectResumeFile(page,inspection,target.id,{name:'fictional.pdf',mimeType:'application/pdf',buffer:Buffer.from('%PDF-invalid-fixture-only')},async()=>{guards++;},()=>attempts++);
 assert.equal(await page.locator('#resume').evaluate(input=>(input as HTMLInputElement).files?.[0]?.name),'fictional.pdf');assert.equal(await page.locator('#photo').evaluate(input=>(input as HTMLInputElement).files?.length),0);assert.equal(attempts,1);assert.ok(guards>=2);checks.push('only-explicit-file-input-receives-host-bytes');
 await page.locator('#resume').evaluate(element=>element.setAttribute('accept','image/*'));await assert.rejects(selectResumeFile(page,inspection,target.id,{name:'fictional.pdf',mimeType:'application/pdf',buffer:Buffer.from('%PDF-fixture')},async()=>{}),/入口已经变化/);await page.locator('#resume').evaluate(element=>element.setAttribute('accept','.pdf,.docx'));checks.push('changed-input-invalidates-selection');
 const profile={...fixtureProfile,fullName:'虚构本机姓名',phone:'13000000000',skills:['已确认测试技能']};
 const result=await runUniversalFormAgent({page,profile,getProfile:async()=>profile,getGeneration:()=>0,signal:new AbortController().signal,directory:join(directory,'host-only'),taskId:'host-only',contextId:'same-local-doc'});
 assert.equal(result.modelRequests,0);assert.equal(await page.locator('#name').inputValue(),profile.fullName);assert.equal(await page.locator('#phone').inputValue(),profile.phone);assert.equal(await page.evaluate(()=>(window as any).submissions??0),0);checks.push('parser-errors-repaired-by-script-with-zero-model-calls');
 provider=await BackgroundModelProvider.create({mode:'live',provider:'custom',modelId:'fixture-only',apiKey:'invalid-local-fixture-only',baseURL:origin+'/v1'},2500,'universal');
 const options={page,profile,getProfile:async()=>profile,getGeneration:()=>0,signal:new AbortController().signal,provider,contextId:'same-local-doc'};
 const one=await runUniversalFormAgent({...options,directory:join(directory,'decision-once'),taskId:'decision-once'});assert.equal(requests,1);assert.ok(one.modelRequests===1);checks.push('remaining-interpretation-uses-one-model-request');
 const two=await runUniversalFormAgent({...options,directory:join(directory,'unchanged'),taskId:'unchanged'});assert.equal(requests,1);assert.equal(two.modelRequests,0);assert.equal(await page.evaluate(()=>(window as any).changes),1);assert.equal(await page.evaluate(()=>(window as any).submissions??0),0);checks.push('unchanged-second-run-does-not-reupload-or-reask-model');
 const report={resumeRepairCheck:true,ok:true,checks,localMockModelRequests:requests,paidRequests:0,externalRequests:0,normalDataAccessed:false,submissions:0};await writeFile(join(directory,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({...report,directory}));
}catch(error){failed=true;console.error(error);}finally{provider?.close();await attachment?.close();window.destroy();server.closeAllConnections();await new Promise<void>(done=>server.close(()=>done()));app.exit(failed?1:0);}
